return $input.all().map(item => {
    const row = item.json;

    // 1. Reformateo de FECHA_FACTURA: "16/01/2026 ..." -> "2026-01-16"
    let fechaISO = "";
    if (row.FECHA_FACTURA) {
        const soloFecha = row.FECHA_FACTURA.split(" ")[0]; 
        const partes = soloFecha.split("/"); 
        if (partes.length === 3) {
            fechaISO = `${partes[2]}-${partes[1]}-${partes[0]}`;
        }
    }

    // 2. Limpieza de FACTURA: Recortar hasta que empiece en "AD"
    let facturaLimpia = row.FACTURA || "";
    if (typeof facturaLimpia === "string") {
        const posAD = facturaLimpia.toUpperCase().indexOf("AD");
        if (posAD !== -1) {
            facturaLimpia = facturaLimpia.substring(posAD);
        }
    }

    // 3. Formateo de FLETE_ALIANZA a Moneda ($)
    let fleteFormateado = row.FLETE_ALIANZA;
    if (fleteFormateado !== undefined && fleteFormateado !== null) {
        // Convierte a número por si viene como texto y aplica formato
        fleteFormateado = `$${Number(fleteFormateado).toFixed(2)}`;
    }

    // 4. Retorno con los cambios aplicados
    return {
        json: {
            RASTREO: row.RASTREO,
            PESO: row.PESO,
            TOTAL: row.IMPTE_ANTES_DE_DESCTO,
            FACTURA: facturaLimpia,
            SUBTOTAL: row.SUBTOTAL,
            FECHA_FACTURA: fechaISO,
            FLETE: fleteFormateado // Ahora incluye el símbolo $ y decimales
        }
    };
});

const items = $input.all();
if (items.length === 0) return [];

// 1. DEFINICIÓN MANUAL: Molde estricto de 8 columnas
const columnNames = ["Fecha", "Tipo", "numero", "Concepto", "Referencia", "cargo", "abono", "Cleaned_Factura"];

// Colores definidos
const redText = { red: 0.8, green: 0, blue: 0 };
const headerBg = { red: 0.7, green: 0.7, blue: 0.7 };
const softGrid = { red: 0.85, green: 0.85, blue: 0.85 }; // Gris cuadrícula Excel

// 2. Mapear datos utilizando el patrón de seguridad [null, ...items]
const rows = [null, ...items].map((item, rowIndex) => {
  const isHeader = rowIndex === 0;
  const rowData = isHeader ? {} : item.json;

  return {
    values: columnNames.map((colName) => {
      let rawValue = isHeader ? colName : rowData[colName];

      // Limpieza de Fecha para evitar la marca de tiempo de n8n
      if (!isHeader && colName === "Fecha" && rawValue) {
          rawValue = String(rawValue).split("T")[0];
      }

      // REGLA: Llenar campos vacíos con 0
      const isEmpty = rawValue === null || rawValue === undefined || String(rawValue).trim() === "";
      if (!isHeader && isEmpty) {
          rawValue = 0;
      }

      const strVal = String(rawValue || "0").trim();

      // Lógica de detección: cargo y abono son moneda, Fecha se excluye de parseFloat
      const isDateColumn = colName === "Fecha"; 
      const numericValue = parseFloat(strVal.replace(/[$,]/g, ''));
      const isNumeric = !isHeader && !isNaN(numericValue) && !isDateColumn;

      const isMoney = isNumeric && (colName === "cargo" || colName === "abono");
      const isNegative = isNumeric && numericValue < 0;

      const cellFormat = {
        textFormat: {
          foregroundColor: isNegative ? redText : { red: 0, green: 0, blue: 0 },
          bold: isHeader,
          fontSize: isHeader ? 11 : 10
        },
        backgroundColor: isHeader ? headerBg : { red: 1, green: 1, blue: 1 },
        horizontalAlignment: (isNumeric || isMoney) ? "RIGHT" : "LEFT",

        // INTEGRACIÓN DE LÍNEAS GRISES TENUES PARA EXCEL
        borders: {
          top: { style: "SOLID", color: softGrid },
          bottom: { style: "SOLID", color: softGrid },
          left: { style: "SOLID", color: softGrid },
          right: { style: "SOLID", color: softGrid }
        }
      };

      const cellData = {};

      if (isHeader) {
        cellData.userEnteredValue = { stringValue: strVal };
        cellData.userEnteredFormat = cellFormat;
      } else if (isMoney) {
        cellData.userEnteredValue = { numberValue: numericValue };
        cellData.userEnteredFormat = { 
          ...cellFormat, 
          numberFormat: { type: "CURRENCY", pattern: "$#,##0.00" } 
        };
      } else if (isNumeric) {
        cellData.userEnteredValue = { numberValue: numericValue };
        cellData.userEnteredFormat = cellFormat;
      } else {
        cellData.userEnteredValue = { stringValue: strVal };
        cellData.userEnteredFormat = cellFormat;
      }

      return cellData;
    })
  };
});

return [{ json: { rowData: rows } }];

// 1. Cargamos y normalizamos la lista de referencia (Partiendo desde "AD")
const listaReferencia = $("Facturas_N").all().map(i => {
    const name = i.json.fileName.toString().trim().toUpperCase();
    const posAD = name.indexOf("AD");
    // Si encuentra "AD", corta desde ahí; si no, deja el nombre original
    return posAD !== -1 ? name.substring(posAD) : name;
});

// 2. Filtramos el Excel (Input actual)
return $input.all().filter(item => {
    const facturaExcel = item.json.FACTURA;
    if (!facturaExcel) return false;

    // Normalización inicial: quitar caracteres especiales y espacios
    let valExcel = facturaExcel.toString().replace(/[^a-zA-Z0-9]/g, '').trim().toUpperCase();

    // Aplicamos la misma regla de limpieza: buscar el inicio en "AD"
    const posADExcel = valExcel.indexOf("AD");
    const cleanExcel = posADExcel !== -1 ? valExcel.substring(posADExcel) : valExcel;

    // Comprobación de coincidencia exacta sobre valores normalizados
    // Ejemplo: 'AD104313' === 'AD104313'
    return listaReferencia.some(idLista => idLista === cleanExcel);
});

// 1. Cargamos y normalizamos la lista de referencia (Partiendo desde "AD")
const listaReferencia = $("Facturas_E").all().map(i => {
    const name = i.json.fileName.toString().trim().toUpperCase();
