// 1. Obtención y limpieza de facturas N y E
const facturasN = $("Facturas_N").all().map(i => i.json.fileName.toString().replace(/^LMM/, "").trim());
const facturasE = $("Facturas_E").all().map(i => i.json.fileName.toString().replace(/^LMM/, "").trim());

const getTag = (inv) => {
  if (inv === undefined || inv === null || inv === "") return "";
  const s = inv.toString().trim();
  if (facturasN.includes(s)) return "N";
  if (facturasE.includes(s)) return "E";
  return "";
};

const itemsData = items.map(i => i.json);
// Extraemos las llaves del JSON (que representan la Fila 1 del Excel original)
const keys = Object.keys(itemsData[0]).filter(k => k !== 'row_number');

// RECONSTRUCCIÓN DINÁMICA DE LA FILA 1
const row1 = keys.map(k => k.startsWith('col_') ? "" : k);
row1.push(""); // Espacio para Columna W (Tag)

// MAPEO DE FILAS POR SU NÚMERO REAL PARA PRESERVAR ESPACIOS VACÍOS
const rowsMap = {};
let maxRow = 1;
for (const item of itemsData) {
  // Capturamos el valor real: si es 0, dejamos 0. Si es nulo/undefined, dejamos "".
  rowsMap[item.row_number] = keys.map(k => (item[k] === 0 || item[k]) ? item[k] : "");
  if (item.row_number > maxRow) maxRow = item.row_number;
}

const finalMatrix = [row1];
let tempBlock = [];
let currentTableType = 0; // 1: Detalle, 2: Resumen/Matriz

for (let i = 2; i <= maxRow; i++) {
  const rowArr = rowsMap[i] || new Array(keys.length).fill("");
  const colA = (rowArr[0] !== undefined && rowArr[0] !== null) ? rowArr[0].toString().trim() : "";

  // Detección de encabezados
  const isHeader1 = colA === "Rastreo";
  const isHeader2 = colA === "Factura";
