const items = $input.all();
if (items.length === 0) return [];

// 1. OBTENCIÓN DE IDs
const spreadsheetId = $("crear spreadsheet").first().json.spreadsheetId;

const sheetData = $("Agregar Diferencias").first().json;
if (!sheetData.replies || !sheetData.replies[0] || !sheetData.replies[0].addSheet) {
    throw new Error("El nodo referenciado no contiene la respuesta de creación de hoja. Verifique su ejecución.");
}
const sheetId = sheetData.replies[0].addSheet.properties.sheetId;

// 2. CONFIGURACIÓN DE DISEÑO
const columnNames = [
    'FACTURA', 'FLETE', 'RAD', 'EAD', 'SEGURO', 'ACUSE', 'COD', 'OTROS',
    'DESCUENTO', 'SUBTOTAL', 'IVA', 'IVA_RET', 'TOTAL', 'abono', 'RESULTADO'
];

const redText = { red: 0.8, green: 0, blue: 0 };
const softGrid = { red: 0.85, green: 0.85, blue: 0.85 };

// 3. GENERACIÓN DE FILA DE ENCABEZADOS (Fila 0)
const headerRow = {
  values: columnNames.map(() => ({
    userEnteredFormat: {
      backgroundColor: { red: 0.7, green: 0.7, blue: 0.7 },
      textFormat: { bold: true, fontSize: 11, fontFamily: "Arial" },
      horizontalAlignment: "LEFT",
      borders: { top: { style: "SOLID", color: softGrid }, bottom: { style: "SOLID", color: softGrid }, left: { style: "SOLID", color: softGrid }, right: { style: "SOLID", color: softGrid } }
    }
  }))
};

// 4. GENERACIÓN DE FILAS DE DATOS
const dataRows = items.map((item) => {
  const rowData = item.json;

  return {
    values: columnNames.map((colName) => {
      const rawValue = rowData[colName];
      const strVal = String(rawValue || "0").trim();
      const numericValue = parseFloat(strVal.replace(/[$,]/g, ''));

      const isFactura = colName === "FACTURA";
      const isNumeric = !isNaN(numericValue) && !isFactura;
      const isNegative = isNumeric && numericValue < 0;

      const format = {
        textFormat: { 
            foregroundColor: isNegative ? redText : { red: 0, green: 0, blue: 0 }, 
            bold: false, 
            fontSize: 10, 
            fontFamily: "Arial" 
        },
        backgroundColor: { red: 1, green: 1, blue: 1 },
        horizontalAlignment: isNumeric ? "RIGHT" : "LEFT",
        wrapStrategy: "CLIP",
        borders: { top: { style: "SOLID", color: softGrid }, bottom: { style: "SOLID", color: softGrid }, left: { style: "SOLID", color: softGrid }, right: { style: "SOLID", color: softGrid } }
      };

      if (isFactura) {
        format.numberFormat = { type: "TEXT" };
      } else if (isNumeric) {
        format.numberFormat = { type: "CURRENCY", pattern: "$#,##0.00" };
      }

      return { userEnteredFormat: format };
    })
  };
});

// 5. SALIDA CONSOLIDADA
return [{
    json: {
        spreadsheet_id: spreadsheetId,
        json_formato_raw: JSON.stringify({
            requests: [
                {
                    updateCells: {
                        rows: [headerRow, ...dataRows],
                        fields: "userEnteredFormat",
                        start: { sheetId: sheetId, rowIndex: 0, columnIndex: 0 }
                    }
                }
            ]
        })
    }
}];

const items = $input.all();

return items.filter(item => {
    const json = item.json;

    // Se exige la existencia de los campos básicos. Si es nulo, indefinido o vacío, se elimina.
    return json.GUIA && json.FACTURA;
});
